parameters.functionCode:
// Parse payload de dispatch em massa
const payload = $json.body || $json;

return {
  organizationId: payload.organizationId,
  selectedLeads: payload.selectedLeads || [],
  messageText: payload.messageText || '',
  targetInstance: payload.targetInstance || 'default',
  dispatchId: Math.random().toString(36).substr(2, 9),
  triggeredAt: new Date().toISOString(),
  batchSize: 50,
  antiBanDelayMs: 1000 + Math.floor(Math.random() * 4000)
};

