parameters.functionCode:
// Processa leads em batches com delay anti-ban
const leads = $json.selectedLeads || [];
const batchSize = $json.batchSize || 50;
const delayMs = $json.antiBanDelayMs || 2000;

const batches = [];
for (let i = 0; i < leads.length; i += batchSize) {
  batches.push(leads.slice(i, i + batchSize));
}

return {
  dispatchId: $json.dispatchId,
  organizationId: $json.organizationId,
  totalLeads: leads.length,
  batchCount: batches.length,
  batches: batches,
  delayMs: delayMs,
  targetInstance: $json.targetInstance,
  messageText: $json.messageText
};

